function detect(): Locale {
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'en' || stored === 'vi-VN') return stored
  } catch { /* Display the application even when durable checkout is unavailable. */ }
  return typeof navigator !== 'undefined' && navigator.languages?.some(value => value.toLowerCase().startsWith('vi')) ? 'vi-VN' : 'en'
}

export const locale = ref<Locale>(detect())
export const htmlLang = computed(() => locale.value)

export function setLocale(value: Locale) {
  locale.value = value
  try { localStorage.setItem(STORAGE_KEY, value) } catch { /* Locale still works for this visit. */ }
  if (typeof document !== 'undefined') document.documentElement.lang = value
}

export function t(key: string, values: Record<string, string | number> = {}) {
  const message = locale.value === 'vi-VN' ? vietnamese[key] ?? key : key
  return message.replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? `{${name}}`))
}

export function commerceCount(variants: number, units: number) {
  if (locale.value === 'vi-VN') return `${variants} phiên bản · ${units} sản phẩm`
  return `${variants} ${variants === 1 ? 'variant' : 'variants'} · ${units} ${units === 1 ? 'unit' : 'units'}`
}

export function statusLabel(value: string) {
  const normalized = value.toLowerCase().replaceAll('_', ' ').replace(/^\w/, letter => letter.toUpperCase())
  return t(normalized)
}

// Re-render already displayed, fixed error copy when the language changes.
export function messageLabel(message: string) {
  const key = Object.entries(vietnamese).find(([, value]) => value === message)?.[0] ?? message
  return t(key)
}

if (typeof document !== 'undefined') document.documentElement.lang = locale.value
